@startuml

class Course {
  + Name : string
}

class Edition {
  + NumberOfParticipants : int
}

class Lesson {
  + Date : date
  + StartTime : time
  + Duration : int
}

class Resource {
  + Name : string
}

class Teacher {
  + Name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {}

class ExternalAuditor {}

class Assignment {
}

class LessonResource {
}

Course "1" -- "1..*" Edition : has
Edition "1" *-- "1..*" Lesson : organized into
Edition "1" -- "0..*" MasterStudent : enrolled
Edition "1" -- "0..*" ExternalAuditor : enrolled
Course "1" -- "1" InternalTeacher : responsible

Teacher "1..*" -- "0..*" Lesson : teaches
Teacher "1" -- "*" Assignment : assigned to
Assignment "*" -- "1" Course : for

Lesson "1" -- "0..*" LessonResource : requires
LessonResource "*" -- "1" Resource : uses

@enduml

